function sharedMentor(tree, a, b) {
  const nodes = [];
  const root = { value: tree[0], left: null, right: null };
  nodes.push(root);
  for (let i = 1, head = 0; i < tree.length; head++) {
    const node = nodes[head];
    if (tree[i] !== null) nodes.push(node.left = { value: tree[i], left: null, right: null });
    i++;
    if (i < tree.length && tree[i] !== null) nodes.push(node.right = { value: tree[i], left: null, right: null });
    i++;
  }
  const path = (target) => {
    const out = [];
    let node = root;
    while (node) {
      out.push(node.value);
      if (node.value === target) break;
      node = target < node.value ? node.left : node.right;
    }
    return out;
  };
  const pa = path(a), pb = path(b);
  let i = 0;
  while (i < pa.length && i < pb.length && pa[i] === pb[i]) i++;
  return pa[i - 1];
}

